package yagen.waitmydawn.mkb_export.client;

import com.google.gson.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.entity.npc.VillagerTrades;
import net.minecraft.world.item.*;
import java.util.*;

/** 枚举候选工厂而非生成少量 MerchantOffer；动态工厂保留明确的覆盖缺口。 */
final class TradeRules {
    static JsonArray capture(MinecraftServer server){
        var rows=new JsonArray();
        boolean experimental=Platform.tradeRebalance(server);
        var professions=experimental?Platform.experimentalTrades():VillagerTrades.TRADES;
        VillagerTrades.TRADES.keySet().stream().sorted(Comparator.comparing(p->BuiltInRegistries.VILLAGER_PROFESSION.getKey(p).toString())).forEach(profession->{
            var pools=professions.getOrDefault(profession,VillagerTrades.TRADES.get(profession));
            if(pools!=null)pools.keySet().intStream().sorted().forEach(level->rows.add(pool(server,"minecraft:villager",BuiltInRegistries.VILLAGER_PROFESSION.getKey(profession).toString(),level,2,pools.get(level),experimental)));
        });
        if(experimental){int index=0;for(var pair:Platform.experimentalWandering())rows.add(pool(server,"minecraft:wandering_trader","minecraft:none",++index,pair.getRight(),pair.getLeft(),true));}
        else VillagerTrades.WANDERING_TRADER_TRADES.keySet().intStream().sorted().forEach(level->rows.add(pool(server,"minecraft:wandering_trader","minecraft:none",level,level==1?5:1,VillagerTrades.WANDERING_TRADER_TRADES.get(level),false)));
        return rows;
    }
    private static JsonObject pool(MinecraftServer server,String entity,String profession,int level,int draws,VillagerTrades.ItemListing[] factories,boolean experimental){
        var row=new JsonObject();row.addProperty("id","mkb_export:trade/"+entity.replace(':','/')+"/"+profession.replace(':','/')+"/"+level);row.addProperty("entity",entity);row.addProperty("profession",profession);row.addProperty("level",level);row.addProperty("experimental",experimental);row.addProperty("selection","UNIFORM_WITHOUT_REPLACEMENT");row.addProperty("draws",Math.min(draws,factories.length));row.addProperty("candidateCount",factories.length);var entries=new JsonArray();int resolved=0;
        for(int i=0;i<factories.length;i++){
            var entry=new JsonObject();entry.addProperty("index",i);entry.addProperty("weight",1);entry.addProperty("selectionProbability",yagen.waitmydawn.mkb_export.core.TradePoolSemantics.inclusion(factories.length,1,draws));entry.addProperty("factory",factories[i].getClass().getName());
            try{adapt(entry,factories[i],server);if(!entry.has("status"))entry.addProperty("status","DECLARATIVE");if(!entry.get("status").getAsString().equals("UNSUPPORTED"))resolved++;}
            catch(Exception failure){entry.addProperty("status","UNSUPPORTED");entry.addProperty("reason",EntitySamples.describe(failure));}
            entries.add(entry);
        }
        var fixedGroups=new java.util.TreeMap<String,java.util.List<Integer>>();
        for(var element:entries){var entry=element.getAsJsonObject();if(!entry.get("status").getAsString().equals("DECLARATIVE")||entry.has("disabled"))continue;var signature=entry.deepCopy();for(String field:List.of("index","weight","selectionProbability","factory"))signature.remove(field);fixedGroups.computeIfAbsent(signature.toString(),ignored->new ArrayList<>()).add(entry.get("index").getAsInt());}
        var grouped=new JsonArray();for(var group:fixedGroups.values()){var value=new JsonObject();var indices=new JsonArray();group.forEach(indices::add);value.add("entryIndices",indices);value.addProperty("atLeastOneFactoryProbability",yagen.waitmydawn.mkb_export.core.TradePoolSemantics.inclusion(factories.length,group.size(),draws));grouped.add(value);}row.add("identicalFixedOfferGroups",grouped);
        row.add("entries",entries);VerifiedIronsTrades.groups(row,factories,server);row.addProperty("resolved",resolved);row.addProperty("coverage",resolved==factories.length?"COMPLETE":"PARTIAL");row.addProperty("limitation","Selection probability is factory inclusion, not a specific random enchantment or final fulfilled offer; failed/null factories and contextual hooks may reduce actual offers");return row;
    }
    private static void adapt(JsonObject row,Object factory,MinecraftServer server)throws Exception {
        String name=factory.getClass().getName();
        if(!name.startsWith("net.minecraft.world.entity.npc.VillagerTrades$")){if(VerifiedStaticTrades.adapt(row,factory,server)||VerifiedIronsTrades.adapt(row,factory,server)||TradeAdapters.adapt(row,factory,server))return;row.addProperty("status","UNSUPPORTED");row.addProperty("reason","Programmatic mod trade factory requires a declarative adapter; it was not sampled");return;}
        String kind=name.substring(name.lastIndexOf('$')+1);var inputs=new JsonArray();JsonObject output;
        switch(kind){
            case "ItemsForEmeralds"->{inputs.add(stack(Items.EMERALD,RuleFields.number(factory,"emeraldCost"),server));var raw=RuleFields.get(factory,"itemStack");output=Platform.knowledgeStack((ItemStack)raw,server);if(!Platform.modernTrades())output=TradeRules.stack(((ItemStack)raw).getItem(),RuleFields.number(factory,"numberOfItems"),server);Platform.tradeProvider(row,factory);}
            case "EmeraldForItems"->{if(Platform.modernTrades()){inputs.add(Platform.knowledgeCost(RuleFields.get(factory,"itemStack"),server));output=stack(Items.EMERALD,RuleFields.number(factory,"emeraldAmount"),server);}else{inputs.add(stack((Item)RuleFields.get(factory,"item"),RuleFields.number(factory,"cost"),server));output=stack(Items.EMERALD,1,server);}}
            case "ItemsAndEmeraldsToItems"->{inputs.add(stack(Items.EMERALD,RuleFields.number(factory,"emeraldCost"),server));if(Platform.modernTrades()){inputs.add(Platform.knowledgeCost(RuleFields.get(factory,"fromItem"),server));output=Platform.knowledgeStack((ItemStack)RuleFields.get(factory,"toItem"),server);Platform.tradeProvider(row,factory);}else{var from=Platform.knowledgeStack((ItemStack)RuleFields.get(factory,"fromItem"),server);from.addProperty("count",RuleFields.number(factory,"fromCount"));inputs.add(from);output=Platform.knowledgeStack((ItemStack)RuleFields.get(factory,"toItem"),server);output.addProperty("count",RuleFields.number(factory,"toCount"));}}
            case "EmeraldsForVillagerTypeItem"->{var variants=new JsonArray();var map=(Map<?,?>)RuleFields.get(factory,"trades");for(var variant:map.entrySet()){var value=new JsonObject();value.addProperty("villagerType",BuiltInRegistries.VILLAGER_TYPE.getKey((net.minecraft.world.entity.npc.VillagerType)variant.getKey()).toString());value.add("input",stack((Item)variant.getValue(),RuleFields.number(factory,"cost"),server));variants.add(value);}inputs.add(new JsonObject());row.add("conditionalInputs",variants);output=stack(Items.EMERALD,1,server);row.addProperty("status","RANDOM_RULE");row.addProperty("condition","VillagerDataHolder required; select input by villager biome type");row.add("inputs",inputs);row.add("output",output);row.addProperty("maxUses",RuleFields.number(factory,"maxUses"));row.addProperty("villagerXp",RuleFields.number(factory,"villagerXp"));row.addProperty("priceMultiplier",0.05);return;}
            case "EnchantedItemForEmeralds"->{int base=RuleFields.number(factory,"baseEmeraldCost");var price=stack(Items.EMERALD,1,server);price.remove("count");price.addProperty("minCount",Math.min(64,base+5));price.addProperty("maxCount",Math.min(64,base+19));inputs.add(price);output=stack(((ItemStack)RuleFields.get(factory,"itemStack")).getItem(),1,server);output.addProperty("dynamicState",true);row.addProperty("status","RANDOM_RULE");row.addProperty("randomRule","EnchantmentHelper.enchantItem at uniform enchantment power 5..19; price=min(64,baseEmeraldCost+power), correlated with power. Enchantment eligibility follows the current game version registry/tag rules");}
            case "DyedArmorForEmeralds"->{inputs.add(stack(Items.EMERALD,RuleFields.number(factory,"value"),server));output=stack((Item)RuleFields.get(factory,"item"),1,server);output.addProperty("dynamicState",true);row.addProperty("status","RANDOM_RULE");row.addProperty("randomRule","If dyeable, mix one uniform dye from 16 colors, plus an independent extra dye when nextFloat>0.7 and another when nextFloat>0.8; use vanilla dye mixing");row.add("inputs",inputs);row.add("output",output);row.addProperty("maxUses",RuleFields.number(factory,"maxUses"));row.addProperty("villagerXp",RuleFields.number(factory,"villagerXp"));row.addProperty("priceMultiplier",0.2);return;}
            case "SuspiciousStewForEmerald"->{inputs.add(stack(Items.EMERALD,1,server));output=Platform.stewStack(factory,server);row.add("inputs",inputs);row.add("output",output);row.addProperty("maxUses",12);row.addProperty("villagerXp",RuleFields.number(factory,"xp"));row.addProperty("priceMultiplier",((Number)RuleFields.get(factory,"priceMultiplier")).doubleValue());return;}
            case "TippedArrowForItemsAndEmeralds"->{inputs.add(stack(Items.EMERALD,RuleFields.number(factory,"emeraldCost"),server));inputs.add(stack((Item)RuleFields.get(factory,"fromItem"),RuleFields.number(factory,"fromCount"),server));var choices=Platform.tradedPotionOutputs(factory,server);row.add("outputAlternatives",choices);output=stack(((ItemStack)RuleFields.get(factory,"toItem")).getItem(),RuleFields.number(factory,"toCount"),server);output.addProperty("dynamicState",true);row.addProperty("status","RANDOM_RULE");row.addProperty("randomRule","Uniform selection among nonempty-effect, brewable potions; empty candidates may prevent offer generation");}
            case "TreasureMapForEmeralds"->{inputs.add(stack(Items.EMERALD,RuleFields.number(factory,"emeraldCost"),server));inputs.add(stack(Items.COMPASS,1,server));output=stack(Items.FILLED_MAP,1,server);output.addProperty("dynamicState",true);row.addProperty("status","RANDOM_RULE");row.addProperty("destinationTag",((net.minecraft.tags.TagKey<?>)RuleFields.get(factory,"destination")).location().toString());row.addProperty("condition","ServerLevel required; findNearestMapStructure within radius100, skipKnownStructures=true; null result suppresses this offer. Coordinates depend on trader position");row.add("inputs",inputs);row.add("output",output);row.addProperty("maxUses",RuleFields.number(factory,"maxUses"));row.addProperty("villagerXp",RuleFields.number(factory,"villagerXp"));row.addProperty("priceMultiplier",0.2);return;}
            case "FailureItemListing"->{row.add("inputs",inputs);row.add("output",new JsonObject());row.addProperty("disabled",true);row.addProperty("condition","This factory always returns null");return;}
            case "EnchantBookForEmeralds"->{var price=stack(Items.EMERALD,1,server);price.remove("count");price.addProperty("dynamicCount",true);inputs.add(price);inputs.add(stack(Items.BOOK,1,server));output=stack(Items.ENCHANTED_BOOK,1,server);var candidates=Platform.tradeEnchantments(factory,server);row.add("randomOutputs",candidates);row.addProperty("status","RANDOM_RULE");row.addProperty("priceRule","For uniformly chosen enchantment and uniformly chosen allowed level L: min(64,(2+uniformInt(0,4+10*L)+3*L)*(doublePrice?2:1)); empty candidate pool follows version-specific behavior; NeoForge 1.21.1 yields one ordinary book for one emerald plus one book");row.addProperty("maxUses",12);row.addProperty("priceMultiplier",0.2);row.addProperty("villagerXp",RuleFields.number(factory,"villagerXp"));}
            default->{row.addProperty("status","UNSUPPORTED");row.addProperty("reason","Unadapted vanilla random/contextual factory: "+kind);return;}
        }
        row.add("inputs",inputs);row.add("output",output);
        if(!kind.equals("EnchantBookForEmeralds")){row.addProperty("maxUses",RuleFields.number(factory,"maxUses"));row.addProperty("villagerXp",RuleFields.number(factory,"villagerXp"));row.addProperty("priceMultiplier",((Number)RuleFields.get(factory,"priceMultiplier")).doubleValue());}
    }
    static JsonObject stack(Item item,int count,MinecraftServer server){return Platform.knowledgeStack(new ItemStack(item,count),server);}
    private TradeRules(){}
}
